package com.loyu3c.rental;

import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.zip.*;

/** Minimal OOXML workbook: numeric money cells, inline text, no formulas/macros. */
final class OwnerWorkbook {
    private static final String NS="http://schemas.openxmlformats.org/spreadsheetml/2006/main";
    private static String xml(String value){StringBuilder b=new StringBuilder();value.codePoints().filter(c->c==9||c==10||c==13||c>=32&&c<=0xD7FF||c>=0xE000&&c<=0xFFFD||c>=0x10000&&c<=0x10FFFF).forEach(b::appendCodePoint);return b.toString().replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;");}
    private static String col(int n){String s="";for(n++;n>0;n=(n-1)/26)s=(char)('A'+(n-1)%26)+s;return s;}
    private static String sheet(List<Object[]> rows,double[] widths,boolean filter){StringBuilder b=new StringBuilder("<?xml version=\"1.0\" encoding=\"UTF-8\"?><worksheet xmlns=\""+NS+"\"><sheetViews><sheetView workbookViewId=\"0\"><pane ySplit=\"1\" topLeftCell=\"A2\" activePane=\"bottomLeft\" state=\"frozen\"/></sheetView></sheetViews><sheetFormatPr defaultRowHeight=\"24\"/><cols>");for(int i=0;i<widths.length;i++)b.append("<col min=\"").append(i+1).append("\" max=\"").append(i+1).append("\" width=\"").append(widths[i]).append("\" customWidth=\"1\"/>");b.append("</cols><sheetData>");for(int r=0;r<rows.size();r++){b.append("<row r=\"").append(r+1).append("\" ht=\"").append(r==0?42:26).append("\" customHeight=\"1\">");Object[] cells=rows.get(r);for(int c=0;c<cells.length;c++){Object value=cells[c];b.append("<c r=\"").append(col(c)).append(r+1).append("\" s=\"").append(r==0?1:value instanceof Number?2:0).append("\"");if(value instanceof Number)b.append("><v>").append(value).append("</v></c>");else b.append(" t=\"inlineStr\"><is><t xml:space=\"preserve\">").append(xml(value==null?"":value.toString())).append("</t></is></c>");}b.append("</row>");}b.append("</sheetData>");if(filter&&rows.size()>1)b.append("<autoFilter ref=\"A1:").append(col(widths.length-1)).append(rows.size()).append("\"/>");return b.append("</worksheet>").toString();}
    private static void put(ZipOutputStream z,String path,String value)throws IOException{z.putNextEntry(new ZipEntry(path));z.write(value.getBytes(StandardCharsets.UTF_8));z.closeEntry();}
    static void write(OutputStream output,JSONObject report)throws IOException,JSONException {
        List<Object[]> summary=new ArrayList<>(),properties=new ArrayList<>(),tenants=new ArrayList<>();JSONObject total=report.getJSONObject("total");summary.add(new Object[]{report.getString("month")+" 房東月報","金額"});String[] keys={"billed","paid","remaining","cash","topups","expenses","held","net"};String[] names={"本月已建帳單應收","截至月底已抵付帳單","本月帳單未付","本月租金水電實收","本月結算補繳實收","本月分攤支出","月底持有押金","本月淨收款（不含押金／轉帳）"};for(int i=0;i<keys.length;i++)summary.add(new Object[]{names[i],total.getLong(keys[i])});summary.add(new Object[]{"報表口徑","帳單按月份；實收按收到日期，抵付及押金截至月底。"});summary.add(new Object[]{"未建帳單","不表示已繳清；資料仍可逐步補登。"});summary.add(new Object[]{"淨收款","不是銀行餘額或會計損益。押金抵付不重複算現金。"});summary.add(new Object[]{"工作表合計","總覽、各不動產、租約明細是不同層級，不可再跨表加總。"});summary.add(new Object[]{"Google同步","本檔供自行匯入；自動同步與租客雲端權限尚未啟用。"});summary.add(new Object[]{"查看對象","房東報表含所有租客資料，請勿當作租客個別報表分享。"});
        properties.add(new Object[]{"不動產","已建帳單應收","月底已抵付","月帳單未付","租金水電實收","結算補繳實收","分攤支出","月底持有押金","淨收款"});Map<String,String> byId=new HashMap<>();JSONArray p=report.getJSONArray("properties");for(int i=0;i<p.length();i++){JSONObject r=p.getJSONObject(i);byId.put(r.getString("id"),r.getString("name"));properties.add(new Object[]{r.getString("name"),r.getLong("billed"),r.getLong("paid"),r.getLong("remaining"),r.getLong("cash"),r.getLong("topups"),r.getLong("expenses"),r.getLong("held"),r.getLong("net")});}
        tenants.add(new Object[]{"不動產","房號／單位","租客","已建帳單應收","月底已抵付","月帳單未付","租金水電實收","結算補繳實收","月底持有押金","狀態"});JSONArray t=report.getJSONArray("tenants");for(int i=0;i<t.length();i++){JSONObject r=t.getJSONObject(i);tenants.add(new Object[]{byId.get(r.getString("propertyId")),r.getString("code"),r.getString("name"),r.getLong("billed"),r.getLong("paid"),r.getLong("remaining"),r.getLong("cash"),r.getLong("topups"),r.getLong("held"),r.getString("status")});}
        try(ZipOutputStream z=new ZipOutputStream(output)){
            put(z,"[Content_Types].xml","<Types xmlns=\"http://schemas.openxmlformats.org/package/2006/content-types\"><Default Extension=\"rels\" ContentType=\"application/vnd.openxmlformats-package.relationships+xml\"/><Default Extension=\"xml\" ContentType=\"application/xml\"/><Override PartName=\"/xl/workbook.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml\"/><Override PartName=\"/xl/styles.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml\"/><Override PartName=\"/xl/worksheets/sheet1.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml\"/><Override PartName=\"/xl/worksheets/sheet2.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml\"/><Override PartName=\"/xl/worksheets/sheet3.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml\"/></Types>");
            put(z,"_rels/.rels","<Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\"><Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument\" Target=\"xl/workbook.xml\"/></Relationships>");
            put(z,"xl/workbook.xml","<workbook xmlns=\""+NS+"\" xmlns:r=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships\"><sheets><sheet name=\"總覽\" sheetId=\"1\" r:id=\"rId1\"/><sheet name=\"各不動產\" sheetId=\"2\" r:id=\"rId2\"/><sheet name=\"租約明細\" sheetId=\"3\" r:id=\"rId3\"/></sheets></workbook>");
            put(z,"xl/_rels/workbook.xml.rels","<Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\"><Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet\" Target=\"worksheets/sheet1.xml\"/><Relationship Id=\"rId2\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet\" Target=\"worksheets/sheet2.xml\"/><Relationship Id=\"rId3\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet\" Target=\"worksheets/sheet3.xml\"/><Relationship Id=\"rId4\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles\" Target=\"styles.xml\"/></Relationships>");
            put(z,"xl/styles.xml","<styleSheet xmlns=\""+NS+"\"><numFmts count=\"1\"><numFmt numFmtId=\"164\" formatCode=\"#,##0;[Red]-#,##0\"/></numFmts><fonts count=\"2\"><font><sz val=\"11\"/><name val=\"Calibri\"/></font><font><b/><sz val=\"11\"/><color rgb=\"FF533C28\"/><name val=\"Calibri\"/></font></fonts><fills count=\"3\"><fill><patternFill patternType=\"none\"/></fill><fill><patternFill patternType=\"gray125\"/></fill><fill><patternFill patternType=\"solid\"><fgColor rgb=\"FFEEDFD0\"/><bgColor indexed=\"64\"/></patternFill></fill></fills><borders count=\"1\"><border><left/><right/><top/><bottom/><diagonal/></border></borders><cellStyleXfs count=\"1\"><xf numFmtId=\"0\" fontId=\"0\" fillId=\"0\" borderId=\"0\"/></cellStyleXfs><cellXfs count=\"3\"><xf numFmtId=\"0\" fontId=\"0\" fillId=\"0\" borderId=\"0\" xfId=\"0\" applyAlignment=\"1\"><alignment vertical=\"center\"/></xf><xf numFmtId=\"0\" fontId=\"1\" fillId=\"2\" borderId=\"0\" xfId=\"0\" applyAlignment=\"1\"><alignment vertical=\"center\" wrapText=\"1\"/></xf><xf numFmtId=\"164\" fontId=\"0\" fillId=\"0\" borderId=\"0\" xfId=\"0\" applyNumberFormat=\"1\" applyAlignment=\"1\"><alignment horizontal=\"right\" vertical=\"center\"/></xf></cellXfs><cellStyles count=\"1\"><cellStyle name=\"Normal\" xfId=\"0\" builtinId=\"0\"/></cellStyles></styleSheet>");
            put(z,"xl/worksheets/sheet1.xml",sheet(summary,new double[]{46,90},false));put(z,"xl/worksheets/sheet2.xml",sheet(properties,new double[]{26,19,19,19,19,19,19,19,19},true));put(z,"xl/worksheets/sheet3.xml",sheet(tenants,new double[]{26,18,22,19,19,19,19,19,19,26},true));
        }
    }
}
